"use client";

import { Piano as PianoPrimitive } from "@audio-ui/react";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "@/lib/utils";

const pianoVariants = cva("", {
  defaultVariants: {
    size: "default",
  },
  variants: {
    size: {
      default: "h-32",
      lg: "h-40",
      sm: "h-24",
    },
  },
});

interface PianoProps
  extends PianoPrimitive.RootProps,
    VariantProps<typeof pianoVariants> {}

export function Piano({ className, size, ...props }: PianoProps) {
  return (
    <PianoPrimitive.Root
      className="w-full data-[disabled=true]:cursor-not-allowed"
      {...props}
    >
      <PianoPrimitive.Track
        className={cn(
          "rounded-none border border-transparent bg-card shadow-sm ring-1 ring-foreground/10 transition-[color,border-color,box-shadow,opacity] duration-150 ease-out hover:ring-2 hover:ring-ring/30 has-[:focus-visible]:ring-2 has-[:focus-visible]:ring-ring/30 active:ring-2 active:ring-ring/30 has-[:focus-visible]:border-ring active:border-ring motion-reduce:transition-none w-full touch-none select-none overflow-hidden",
          "focus-visible:outline-none",
          "data-[disabled=true]:pointer-events-none data-[disabled=true]:opacity-50",
          pianoVariants({ size }),
          className
        )}
        data-slot="piano"
      >
        <PianoPrimitive.Keys>
          {(note, _color, index) => (
            <PianoPrimitive.Key
              className="top-0 outline-none transition-colors duration-100 ease-out focus-visible:z-20 focus-visible:ring-2 focus-visible:ring-ring/60 focus-visible:ring-inset data-[color=white]:z-0 data-[color=white]:h-full data-[color=white]:border-border data-[color=white]:border-x data-[color=white]:bg-background data-[color=black]:z-10 data-[color=black]:h-[60%] data-[color=black]:rounded-none data-[color=black]:bg-foreground data-[pressed=true]:bg-primary motion-reduce:transition-none cursor-pointer outline-none"
              index={index}
              key={note}
            />
          )}
        </PianoPrimitive.Keys>
      </PianoPrimitive.Track>
    </PianoPrimitive.Root>
  );
}
